WITH filtered AS (SELECT *, CONCAT(category, ' ', brand) AS category_brand, INITCAP(TRIM(product_name)) AS product_name_title, COALESCE(brand, 'N/A') AS brand_filled FROM products WHERE brand IS NOT NULL AND launch_date >= DATE '2023-09-30') SELECT CASE WHEN price >= 1130 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, CASE WHEN cost >= 630 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, supplier_id, SUM(CASE WHEN category = 'Home' THEN stock_qty ELSE 0 END) AS home_stock_qty, PERCENTILE_APPROX(cost, 0.9) AS cost_p90, COUNT(*) FILTER (WHERE category = 'Fashion') AS fashion_rows, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN brand = 'Umbrella' THEN 1 END), 0), 2) AS price_per_umbrella, STDDEV_SAMP(cost) AS cost_stddev, RANK() OVER (PARTITION BY CASE WHEN price >= 1130 THEN 'LARGE' ELSE 'SMALL' END ORDER BY SUM(CASE WHEN category = 'Home' THEN stock_qty ELSE 0 END) DESC) AS home_stock_qty_rank FROM filtered GROUP BY CASE WHEN price >= 1130 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN cost >= 630 THEN 'HIGH' ELSE 'LOW' END, supplier_id ORDER BY fashion_rows
